import { NumberInput } from '@absoluteui/components/number-input';

const host = document.createElement('div');
document.body.append(host);
const quantity = NumberInput.create(host, { label: 'Quantity', name: 'quantity', value: 1, min: 1, max: 99, required: true });
host.addEventListener('aui-change', () => {
  host.dataset.quantity = String(quantity.value ?? '');
});

import { NumberInput } from '@absoluteui/components/number-input';

const host = document.createElement('div');
document.body.append(host);
NumberInput.create(host, {
  label: 'Preis',
  name: 'price',
  locale: 'de-DE',
  min: 0,
  step: 0.01,
  format: { style: 'currency', currency: 'EUR', maximumFractionDigits: 2 },
});

import { NumberInput } from '@absoluteui/components/number-input';

const host = document.createElement('div');
document.body.append(host);
NumberInput.create(host, {
  label: 'Discount',
  min: 0,
  max: 1,
  step: 0.001,
  format: { style: 'percent', maximumFractionDigits: 1 },
  validate: (value) => (value !== null && value > 0.5 ? 'Discounts above 50% need approval.' : null),
});
